  "collected_information": {
    "environment_setup": {
      "python_version": "3.9+",
      "conda_environment": "conda create -n metagpt python=3.9 && conda activate metagpt",
      "main_package_install": "pip install metagpt",
      "config_initialization": "metagpt --init-config (creates ~/.metagpt/config2.yaml)",
      "docker_instructions": "available in README.md",
      "language": "Python 3.9+"
    },
    "test_execution": {
      "test_framework": "pytest",
      "test_command": "pytest tests/ --doctest-modules --cov=./metagpt/ --cov-report=xml:cov.xml --cov-report=html:htmlcov --durations=20 | tee unittest.txt\ncoverage report -m\ngrep -E \"FAILED tests|ERROR tests|[0-9]+ passed,\" unittest.txt",
      "pre_test_script": "sh tests/scripts/run_install_deps.sh",
      "environment_variables": {
        "ALLOW_OPENAI_API_CALL": "0"
      },
      "config_file": "tests/config2.yaml copied to ~/.metagpt/config2.yaml"
    },
    "test_dependencies": {
      "location": "extras_require['test'] in setup.py",
      "packages": [
        "pytest",
        "pytest-asyncio",
        "pytest-cov",
        "pytest-mock",
        "pytest-html",
        "pytest-xdist",
        "pytest-timeout",
        "connexion[uvicorn]~=3.0.5",
        "azure-cognitiveservices-speech~=1.31.0",
        "aioboto3~=11.3.0",
        "chromadb==0.4.14",
        "gradio==3.0.0",
        "grpcio-status==1.48.2",
        "pylint==3.0.3",
        "pybrowsers"
      ],
      "versions": "mostly unspecified for pytest packages"
    },
    "notes": {
      "requirements.txt": "pytest and pytest-mock commented out"
    }
  },
  "terminate": true
}
